def solve(graph, config):
    pending, seen = [config['start']], set()
    blocked = set(config['blocked'])
    while pending:
        node = pending.pop()
        if node in seen or node in blocked:
            continue
        seen.add(node)
        pending.extend(graph.get(node, []))
    return sorted(seen)
